CREATE TABLE IF NOT EXISTS diagnostic_logs(id bigserial PRIMARY KEY,session_id text,log_id text,component text,level text,event text,message text,structured_data jsonb,request_id text,trace_id text,span_id text,frame_id text,candle_id text,signal_id text,trade_id text,evaluation_id text,market_event_id text,code_version text,logged_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS diagnostic_logs_session_time_idx ON diagnostic_logs(session_id,logged_at DESC);
CREATE INDEX IF NOT EXISTS diagnostic_logs_trace_idx ON diagnostic_logs(trace_id);
CREATE TABLE IF NOT EXISTS agent_runs(id bigserial PRIMARY KEY,session_id text,agent_run_id text UNIQUE,agent_id text,agent_name text,agent_role text,agent_version text,model text,provider text,prompt_version text,config_version text,started_at timestamptz,completed_at timestamptz,latency_ms integer,status text,structured_input jsonb,structured_output jsonb,confidence numeric,evidence jsonb,warnings jsonb,error text,fallback_used boolean DEFAULT false,trace_id text,market_event_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS agent_runs_session_idx ON agent_runs(session_id,created_at DESC);
